{

    var value = Document.ToString();
    try
    {
        var res = int.Parse(value);

        return res;
    }
    catch (Exception ex2)
    {
        try
        {
            var res = decimal.Parse(value);
            return res;
        }
        catch (Exception ex3)
        {

            try
            {
                var res = DateTime.Parse(value);
